import React, { useRef, useEffect, useState } from "react";
import { MapContainer, TileLayer, Polyline, CircleMarker, Popup, useMap } from "react-leaflet";
import { Box, Typography, Chip, Paper } from "@mui/material";
import "leaflet/dist/leaflet.css";

// Import Leaflet icons
import L from "leaflet";
import icon from "leaflet/dist/images/marker-icon.png";
import iconShadow from "leaflet/dist/images/marker-shadow.png";

// Fix Leaflet icons
let DefaultIcon = L.icon({
  iconUrl: icon,
  shadowUrl: iconShadow,
  iconSize: [25, 41],
  iconAnchor: [12, 41],
  popupAnchor: [1, -34],
  shadowSize: [41, 41],
});
L.Marker.prototype.options.icon = DefaultIcon;

const MapVisualization = ({ stressData, ratingsData, loading }) => {
  const mapRef = useRef();
  const [busData, setBusData] = useState(null);
  const [lineData, setLineData] = useState(null);

  // Load bus data from CSV
  useEffect(() => {
    const loadBusData = async () => {
      try {
        const response = await fetch("/data/buses.csv");
        const csvText = await response.text();
        const lines = csvText.split("\n");
        const headers = lines[0].split(",");

        const buses = {};
        for (let i = 1; i < lines.length; i++) {
          if (lines[i].trim()) {
            const values = lines[i].split(",");
            const busId = parseInt(values[0]);
            const busName = values[15]; // BusName column
            const voltage = parseFloat(values[1]); // v_nom column
            const longitude = parseFloat(values[2]); // x column
            const latitude = parseFloat(values[3]); // y column

            buses[busId] = {
              id: busId,
              name: busName,
              voltage: voltage,
              coordinates: [latitude, longitude]
            };
          }
        }
        setBusData(buses);
      } catch (error) {
        console.error("Error loading bus data:", error);
      }
    };

    loadBusData();
  }, []);

  // Load line data from GeoJSON
  useEffect(() => {
    const loadLineData = async () => {
      try {
        const response = await fetch("/data/oneline_lines.geojson");
        const geojson = await response.json();
        setLineData(geojson);
      } catch (error) {
        console.error("Error loading line data:", error);
      }
    };

    loadLineData();
  }, []);

  const getStatusColor = (status) => {
    switch (status) {
      case "GOOD":
        return "#4caf50";
      case "WARN":
        return "#ff9800";
      case "BAD":
        return "#f44336";
      default:
        return "#9e9e9e";
    }
  };

  const getLineWeight = (voltage) => {
    if (voltage >= 138) return 6;
    if (voltage >= 69) return 4;
    return 2;
  };

  const getBusSize = (voltage) => {
    if (voltage >= 138) return 12;
    if (voltage >= 69) return 8;
    return 6;
  };

  const getBusColor = (voltage) => {
    if (voltage >= 138) return "#1976d2"; // Blue for 138kV
    if (voltage >= 69) return "#388e3c"; // Green for 69kV
    return "#f57c00"; // Orange for lower voltages
  };

  // Create transmission lines from GeoJSON data
  const createTransmissionLines = () => {
    if (!lineData || !stressData) return [];

    return lineData.features.map((feature, index) => {
      const { BusNumFrom, BusNumTo, nomkv } = feature.properties;
      const coordinates = feature.geometry.coordinates.map(coord => [coord[1], coord[0]]); // Convert [lng, lat] to [lat, lng]

      // Find stress data for this line
      const lineStress = stressData.find(
        (line) => 
          (line.bus0 === BusNumFrom && line.bus1 === BusNumTo) ||
          (line.bus0 === BusNumTo && line.bus1 === BusNumFrom)
      );

      const status = lineStress ? lineStress.status : "UNKNOWN";
      const utilization = lineStress ? lineStress.util : 0;

      return (
        <Polyline
          key={`line-${index}`}
          positions={coordinates}
          color={getStatusColor(status)}
          weight={getLineWeight(nomkv)}
          opacity={0.8}
        >
          <Popup>
            <div>
              <Typography variant="subtitle2" gutterBottom>
                {feature.properties.LineName}
              </Typography>
              <Typography variant="body2">
                <strong>Voltage:</strong> {nomkv} kV<br />
                <strong>Status:</strong> <span style={{ color: getStatusColor(status) }}>{status}</span><br />
                <strong>Utilization:</strong> {utilization ? `${(utilization * 100).toFixed(1)}%` : "N/A"}
              </Typography>
            </div>
          </Popup>
        </Polyline>
      );
    });
  };

  // Create bus markers from bus data
  const createBusMarkers = () => {
    if (!busData || !ratingsData) return [];

    return Object.values(busData).map((bus) => {
      const busRating = ratingsData.find(rating => rating.bus === bus.id);
      const rating = busRating ? busRating.rating_a : 0;

      return (
        <CircleMarker
          key={`bus-${bus.id}`}
          center={bus.coordinates}
          radius={getBusSize(bus.voltage)}
          fillColor={getBusColor(bus.voltage)}
          color="#ffffff"
          weight={2}
          opacity={1}
          fillOpacity={0.8}
        >
          <Popup>
            <div>
              <Typography variant="subtitle2" gutterBottom>
                {bus.name}
              </Typography>
              <Typography variant="body2">
                <strong>Bus ID:</strong> {bus.id}<br />
                <strong>Voltage:</strong> {bus.voltage} kV<br />
                <strong>Rating:</strong> {rating ? `${rating.toFixed(1)} A` : "N/A"}
              </Typography>
            </div>
          </Popup>
        </CircleMarker>
      );
    });
  };

  // Calculate map bounds from actual data
  const calculateBounds = () => {
    if (!busData) return [[21.2, -158.2], [21.7, -157.5]]; // Default bounds for Hawaii

    const coordinates = Object.values(busData).map(bus => bus.coordinates);
    const lats = coordinates.map(coord => coord[0]);
    const lngs = coordinates.map(coord => coord[1]);

    const minLat = Math.min(...lats);
    const maxLat = Math.max(...lats);
    const minLng = Math.min(...lngs);
    const maxLng = Math.max(...lngs);

    // Add some padding
    const latPadding = (maxLat - minLat) * 0.1;
    const lngPadding = (maxLng - minLng) * 0.1;

    return [
      [minLat - latPadding, minLng - lngPadding],
      [maxLat + latPadding, maxLng + lngPadding]
    ];
  };

  const bounds = calculateBounds();

  if (loading) {
    return (
      <Box
        display="flex"
        justifyContent="center"
        alignItems="center"
        height="600px"
        bgcolor="grey.100"
      >
        <Typography variant="h6" color="text.secondary">
          Loading map data...
        </Typography>
      </Box>
    );
  }

  return (
    <Box>
      {/* Legend */}
      <Paper sx={{ p: 2, mb: 2 }}>
        <Typography variant="h6" gutterBottom>
          Map Legend
        </Typography>
        <Box display="flex" flexWrap="wrap" gap={2}>
          <Box display="flex" alignItems="center" gap={1}>
            <Box
              width={20}
              height={4}
              bgcolor="#4caf50"
              borderRadius={1}
            />
            <Typography variant="body2">Good Lines</Typography>
          </Box>
          <Box display="flex" alignItems="center" gap={1}>
            <Box
              width={20}
              height={4}
              bgcolor="#ff9800"
              borderRadius={1}
            />
            <Typography variant="body2">Warning Lines</Typography>
          </Box>
          <Box display="flex" alignItems="center" gap={1}>
            <Box
              width={20}
              height={4}
              bgcolor="#f44336"
              borderRadius={1}
            />
            <Typography variant="body2">Bad Lines</Typography>
          </Box>
          <Box display="flex" alignItems="center" gap={1}>
            <Box
              width={12}
              height={12}
              bgcolor="#1976d2"
              borderRadius="50%"
            />
            <Typography variant="body2">138kV Buses</Typography>
          </Box>
          <Box display="flex" alignItems="center" gap={1}>
            <Box
              width={8}
              height={8}
              bgcolor="#388e3c"
              borderRadius="50%"
            />
            <Typography variant="body2">69kV Buses</Typography>
          </Box>
        </Box>
      </Paper>

      {/* Map */}
      <Box height="600px" border="1px solid #ddd" borderRadius={1}>
        <MapContainer
          ref={mapRef}
          center={[21.4, -157.8]} // Center of Hawaii
          zoom={9}
          style={{ height: "100%", width: "100%" }}
          bounds={bounds}
          boundsOptions={{ padding: [20, 20] }}
        >
          <TileLayer
            attribution='&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'
            url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
          />

          {/* Render transmission lines */}
          {createTransmissionLines()}

          {/* Render bus markers */}
          {createBusMarkers()}
        </MapContainer>
      </Box>
    </Box>
  );
};

export default MapVisualization;
